// Response from creating or processing an invitation. `invite` is a compact invite summary.
// An org-scoped invitation is `sent`, whatever account the email maps to: the invitee joins
// through the emailed link, and `user` is empty (id 0) so the answer does not reveal
// whether the address has an account. It is `accepted`, with a response-only random
// `invite.id` and no email, when the address is already a member of the org. An org-less
// invitation answers the invitee's public summary in `user`, and it is `accepted` with a
// response-only random `invite.id` when the email already maps to a confirmed user.
// `invite.orgId` is present for org-scoped actions.
type UserInviteResponse struct {
	// Safe user summary for UI display.
	User PublicUser `json:"user"`

	// Compact invite summary returned from create-invite endpoints.
	Invite InviteSummary `json:"invite"`
}

